let tempo;
let monShader;
let rayo;
let vax;


function setup() {
  renderer = createCanvas(1112, 834, WEBGL);
  noStroke();
  fill(255);
  monShader = createShader(vert,frag);

}

function draw() {

  this.shader(monShader);

  monShader.setUniform("u_resolution", [width,height]);
  monShader.setUniform("u_lightDir", [1.0,0.2,0.8]);
  monShader.setUniform("u_col", "#77aa99");


  background(0);
  orbitControl();
  translate(0,0,-200);
  rotateY(frameCount*0.01);
  rotateX(frameCount*0.005);

  tempo=millis()*0.005; 
 //============================================= 



  vax=[];

  directionalLight(255, 255, 255, 2, -1, -2);
  fill(255,255,0);
  noStroke();


  for(var i=0;i<360;i++){ 
   vax[i]=createVector(20.0*cos(i*PI/12.0),20.0*sin(i*PI/12.0),0);
   push();
   rotate(tempo*PI/99.0,vax[i]);
   translate(360.0*cos(i*PI/180.0),360.0*sin(i*PI/180.0),0);
   push();


    fill(173+i/5,173+i/5,255-i/5.0); 
    box(10);
    translate(0,0,40);
    sphere(10);
    translate(0,0,-80);
    sphere(10);

   pop();
 pop();}
}

function setCol(shader,uniformName,colStr)
{
  let col = color(colStr*255.0);
  let colArray = col.array;
  colArray.pop();
  shader.setUniform(uniformName,colArray);
}

function repere(e,l){
  push();
  fill(255,0,0);
  translate(l*0.5,0,0);
  box(l,e,e);
  fill(0,255,0);
  translate(-l*0.5,l*0.5,0);
  box(e,l,e);
  fill(0,0,255);
  translate(0,-l*0.5,0,l*0.5);
  box(e,e,l);
  pop();
}


var vert = `

    precision highp float;

    // attributes, in
    attribute vec3 aPosition;
    attribute vec3 aNormal;
    attribute vec2 aTexCoord;

    // attributes, out
    varying vec3 var_vertPos;
    varying vec3 var_vertNormal;
    varying vec2 var_vertTexCoord;
    varying vec4 var_centerGlPosition;

    // matrices
    uniform mat4 uModelViewMatrix;
    uniform mat4 uProjectionMatrix;
    uniform mat3 uNormalMatrix;

    void main() {
      vec3 pos = aPosition; 
      vec4 positionVec4=vec4(aPosition,.0);
      gl_Position = uProjectionMatrix * uModelViewMatrix * vec4(pos, 1.0);
     // 
 //blendMode();
      // set out value
      var_vertPos      = pos;
      var_vertNormal   = aNormal;
      var_vertTexCoord = aTexCoord;
      var_centerGlPosition = uProjectionMatrix * uModelViewMatrix * positionVec4;
    }
`;


var frag = `

precision highp float;

uniform vec2 u_resolution;
uniform vec2 u_mouse;
uniform float u_time;
uniform vec3 u_lightDir;
uniform vec3 u_col;
uniform mat3 uNormalMatrix;

//attributes, in//
varying vec4 var_centerGlPosition;
varying vec3 var_vertNormal;



void main() {

    gl_FragColor = vec4(var_vertNormal,1.0);
}

`;

